from toolz import partition_all

class BadP(list):
    def __len__(self): return super().__len__() + 1
class BadM(list):
    def __len__(self): return super().__len__() - 1

# Various data/n combos that produce partial final partitions -> must raise
import itertools
cases = []
for data in ([1,2], [1,2,3], [1,2,3,4,5,6], list(range(7)), list(range(10))):
    for n in (2,3,4,5):
        for cls in (BadP, BadM):
            got = None
            try:
                got = list(partition_all(n, cls(list(data))))
            except LookupError:
                got = 'RAISED'
            # Determine if final partition is partial (the only place len is used)
            r = len(data) % n
            partial = r != 0 and len(data) > 0
            cases.append((n, len(data), cls.__name__, partial, got))
            if partial and got != 'RAISED':
                print('UNEXPECTED no-raise (partial):', n, len(data), cls.__name__, '->', got)
            if (not partial) and got == 'RAISED':
                print('UNEXPECTED raise (full):', n, len(data), cls.__name__)

print('checked', len(cases), 'cases')
# Verify correct-length lists never raise and match plain list output
for data in ([], [1], [1,2], [1,2,3], list(range(7)), list(range(12))):
    for n in (1,2,3,5):
        a = list(partition_all(n, list(data)))
        b = list(partition_all(n, iter(data)))
        assert a == b, (data, n, a, b)
print('correct sequences match list/iter:', True)
"

